    def __init__(self, expr, variables=None):
        self.expr = expr.replace(" ", "")  # Remove all whitespace for simplicity
        self.pos = 0
        self.variables = variables if variables is not None else {}

    def _peek(self):
        return self.expr[self.pos] if self.pos < len(self.expr) else None

    def _consume(self):
        c = self._peek()
        if c is None:
            raise ValueError("Unexpected end of expression")
        self.pos += 1
        return c

    def _parse_number_or_var(self):
        """Parses a number or variable."""
        start = self.pos
        # Check if it's a variable (starts with alpha/underscore)
        while self.pos < len(self.expr):
            c = self._peek()
            if c and (c.isalnum() or c == '_'):
                self.pos += 1
            else:
                break
        token_str = self.expr[start:self.pos]
        if not token_str:
            raise ValueError(f"Unexpected character at position {self.pos}")

        # Check for number first; assume variable otherwise
        is_digit_start = token_str and (token_str[0].isdigit() or token_str.startswith('.'))
        if is_digit_start:
            try:
                return float(token_str)
            except ValueError:
                raise ValueError(f"Invalid number at position {start}")

        # Variable handling
        var_name = token_str
        if not (var_name[0].isalpha() or var_name[0] == '_'):
            raise ValueError(f"Unexpected character '{self.expr[start]}' at position {start}")
        value = self.variables.get(var_name)
        if value is None:
            raise ValueError(f"Unknown variable '{var_name}'")
        return float(value)

    def _parse_primary(self):
        """Parse a primary expression (number, variable, or parenthesis group)."""
        c = self._peek()
        if c == '(':
            self._consume()  # consume '('
            val = self.parse_expression()
            if not self._match(')'):
                raise ValueError(f"Unbalanced parentheses")
            return val
        elif c and (c.isdigit() or c == '.'):
            start = self.pos
            while self.pos < len(self.expr):
                c = self._peek()
                if c and (c.isdigit() or c == '.'):
                    self.pos += 1
                else:
                    break
            try:
                return float(self.expr[start:self.pos])
            except ValueError:
                raise ValueError(f"Invalid number at position {start}")

        # Else, assume it's a variable name
        elif c and (c.isalpha() or c == '_'):
            return self._parse_number_or_var()
        else:
            if c in ('+', '-', '*', '/', '%', '^'):
                raise ValueError(f"Unexpected operator {c} at position {self.pos}")
            else:
                raise ValueError(f"Invalid character '{c}'")

    def _match(self, expected):
        """Check and consume the next token. Returns True if matched."""
        if self._peek() == expected:
            self._consume()
            return True
        return False

    def parse_expression(self):
        """Parse an expression handling + - with lowest precedence."""
        left = self.parse_term()
        while self.pos < len(self.expr) and self._peek() in ('+', '-'):
            op = self._consume()
            right = self.parse_term()
            if op == '+':
                left += right
            else:
                left -= right
        return float(left)

    def parse_term(self):
        """Parse multiplication, division, modulo terms."""
        left = self.parse_power()
        while self.pos < len(self.expr) and self._peek() in ('*', '/', '%'):
            op = self._consume()
            right = self.parse_power()
            if op == '*':
                left *= right
            elif op == '/':
                if right == 0:
                    raise ValueError("Division by zero")
                left /= right
            else:  # modulo
                if right == 0:
                    raise ValueError("Modulo by zero")
                left %= right
        return float(left)

    def parse_power(self):
        """Parse exponentiation (right-associative)."""
        base = self.parse_unary()
        while self.pos < len(self.expr) and self._peek() == '^':
            self._consume()
            exp = self.parse_power()  # right associative, so recurse here
            base **= exp
        return float(base)

    def parse_unary(self):
        """Parse unary +/- operators (left to right)."""
        sign = 1
        while True:
            c = self._peek()
            if c == '-':
                sign *= -1
                self.pos +=1
            elif c == '+':
                # consume but no change to sign
                self.pos +=1
            else:
                break
        return sign * self.parse_primary()

    def parse(self):
        val = self.parse_expression()
        if self.pos < len(self.expr) and self._peek() is not None:
            raise ValueError(f"Unexpected token at position {self.pos}")
        return float(val)

def evaluate(expr, variables=None):
    parser = Parser(expr, variables)
    try:
        result = parser.parse()
        # Ensure no remaining tokens
        if parser.pos != len(parser.expr):
            raise ValueError("Invalid syntax")
        return result
    except Exception as e:
        raise ValueError(str(e)) from None

    def __str__(self):
        return str(self.expr)
