    def _consume_char(self, expected=None):
        c = self._peek()
        if c is None:
            raise ValueError(f"Unexpected end of expression at position {self.pos}")
        if expected is not None and c != expected:
            raise ValueError(f"Expected '{expected}' but got '{c}'")
