                right_val = self.parse_term()
                if op == '+':
                    value += right_val
                else:
                    value -= right_val
            else:
                break
        return float(value)

    def parse_term(self):
        value = self.parse_factor()
        while True:
            c = self._peek()
            if c in ('*', '/', '%'):
                op = self._consume_char()
                right_val = self.parse_factor()
                if op == '*':
                    value *= right_val
                elif op == '/':
                    if right_val == 0:
                        raise ValueError("Division by zero")
                    value /= right_val
                else:
                    if right_val == 0:
